using System;
using System.Linq;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
namespace Ara {
 public static class SplitBufferTests {
  static void Assert(bool yes,string why){if(!yes)throw new Exception(why);}
  static State New(){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,d);return s;}
  static State Fourth(int delay,int count=3){var s=New();var d=s.Days[0];var record=d.GridBase.Single(x=>x.MealId=="b15").Copy();record.Id="fourth-fact";record.Start=record.Start.AddMinutes(delay);record.Count=count;record.Score=3;record.Satisfaction=4;d.Records.Add(record);return s;}
  public static void Run(Action<string,Action> check,string dir){
   check("split: thirty-minute delay keeps yogurt by dropping its sleep gap",()=>{var s=Fourth(30);var d=s.Days[0];var p=GridEngine.Build(s,d);Assert(p.Blocks.Any(x=>x.MealId=="b16")&&!p.PostFourthRestMinutes.HasValue,"yogurt and preparation retained");Assert(p.Changes.Any(x=>x.Contains("요거트→수면")&&x.Contains("30분 회복"))&&!p.Changes.Any(x=>x.Contains("요거트·준비 제외")),"no omission");Assert(p.Saved==30&&p.Overflow==0&&Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d),"sleep unchanged");});
   check("split: fifty-minute delay retains yogurt until the exact sleep boundary",()=>{var s=Fourth(50);var d=s.Days[0];var p=GridEngine.Build(s,d);Assert(!p.PostFourthRestMinutes.HasValue&&p.Saved==50&&p.Overflow==0,"gap alone recovers fifty");Assert(p.Blocks.Single(x=>x.MealId=="b16").End==Adaptive.EstimatedSleep(s,d,p),"yogurt ends at sleep");Assert(!p.Changes.Any(x=>x.Contains("요거트·준비 제외")),"no omission");});
   check("split: ninety-minute capacity is fifty sleep-gap plus twenty yogurt plus twenty rest",()=>{foreach(int delay in new[]{90,120,180,300}){var s=Fourth(delay);var d=s.Days[0];var p=GridEngine.Build(s,d);Assert(p.PostFourthRestMinutes==120&&p.Saved==90&&p.Overflow==delay-90,"fifty plus twenty plus twenty only");Assert(p.Changes.Any(x=>x.Contains("요거트·준비 제외")&&x.Contains("20분 회복"))&&p.Changes.Any(x=>x.Contains("4끼니→취침 여유 −20분")),"both logged");Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==d.Records[0].End.AddHours(2),"actual fourth end floor");Assert(d.Records[0].Score==3&&d.Records[0].Satisfaction==4,"ratings protected");}});
   check("split: longer actual fourth meal reduces only remaining rest capacity",()=>{var s=Fourth(120,6);var d=s.Days[0];var p=GridEngine.Build(s,d);Assert(p.PostFourthRestMinutes==120&&p.Saved==60&&p.Overflow==60,"fifty gap plus ten yogurt");Assert(p.Changes.Any(x=>x.Contains("요거트·준비 제외")&&x.Contains("10분 회복"))&&!p.Changes.Any(x=>x.Contains("4끼니→취침 여유 −")),"actual duration respected");Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==d.Records[0].End.AddHours(2),"two hours from eating end");});
   check("split: eaten yogurt cannot create removal or bedtime credits",()=>{var s=Fourth(120);var d=s.Days[0];var yogurt=d.GridBase.Single(x=>x.MealId=="b16").Copy();yogurt.Id="eaten-yogurt";yogurt.Start=yogurt.Start.AddMinutes(120);d.Records.Add(yogurt);var p=GridEngine.Build(s,d);Assert(p.Blocks.Any(x=>x.MealId=="b16")&&!p.PostFourthRestMinutes.HasValue,"eaten yogurt stays");Assert(!p.Changes.Any(x=>x.Contains("요거트·준비 제외")||x.Contains("4끼니→취침 여유 −")),"no fabricated credit");});
   check("split: front-buffer retry shares the first pass capacity",()=>{var s=New();var d=s.Days[0];var first=d.GridBase.Single(x=>x.MealId=="b1").Copy();first.Id="actual-first";d.Records.Add(first);var blocks=d.GridBase.Select(x=>x.Copy()).ToList();var zone=blocks.Single(x=>x.Category=="존2");DateTime original=zone.Start;foreach(var b in blocks.Where(x=>x.Start>=original))b.Start=b.Start.AddHours(1);var p=new GridPlan{Blocks=blocks};var method=typeof(Adaptive).GetMethod("FrontWaitBuffer",BindingFlags.NonPublic|BindingFlags.Static);method.Invoke(null,new object[]{s,d,p,first.End,"first"});DateTime after=p.Blocks.Single(x=>x.Category=="존2").Start;method.Invoke(null,new object[]{s,d,p,first.End,"retry"});Assert(p.FrontWaitSpent==30&&after==p.Blocks.Single(x=>x.Category=="존2").Start,"second pass cannot duplicate credit");});
   check("split: removing late facts resets both night credits and front spent amounts",()=>{var s=Fourth(90);var d=s.Days[0];GridEngine.Build(s,d);d.Records.Clear();var p=GridEngine.Build(s,d);Assert(!p.PostFourthRestMinutes.HasValue&&p.FrontWaitSpent==0&&p.Blocks.Any(x=>x.MealId=="b16")&&p.Overflow==0,"recompute from unchanged baseline");});
  }
 }
}
